  const arcs = [
    ...project.arcs.map((arc) => ({ id: arc.id, name: String(arc.name), status: String(arc.status), known: true })).sort(byFirst),
    ...[...first.keys()].filter((id) => !known.has(id)).map((id) => ({ id, name: null, status: null, known: false })).sort(byFirst)
  ];
